// The row cells the person export carries, in its order.
const CELLS = [
  'person-name',
  'person-grade',
  'person-claimed',
  'person-due-total',
  'person-statement-count',
  'person-overdue-total',
  'person-hold',
  'person-retired',
  'person-aliases',
  'person-score',
];

function PersonExportHead() {
  return <th>Export</th>;
}

